  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "targeted_spend": {
        "type": "object",
        "description": "{channel_id: {group_id: $/day}}",
        "additionalProperties": {
          "type": "object",
          "additionalProperties": {
            "type": "number"
          }
        }
      }
    },
    "required": [
      "targeted_spend"
    ]
  },
  "returns": {
    "success": "Ad spend updated (total $300/day):\n  \u2022 LinkedIn Ads \u2192 E1: $200/day\n  \u2022 LinkedIn Ads \u2192 E2: $100/day",
