# Scenario definitions
def bear_signups(wk):
    return 0  # conversion never recovers

def base_signups(wk):
    if wk <= 10:
        return 0
    return min(80, (wk-10)*8)  # slow recovery starting week 11 (~day175) as dev spend closes gap

def bull_signups(wk):
    if wk <= 5:
        return 0
    return min(200, (wk-5)*15)  # faster recovery

scenarios = {
    'bear': dict(first_eval_churn=0.65, repeat_eval_churn=0.25, signups=bear_signups),
    'base': dict(first_eval_churn=0.585, repeat_eval_churn=0.148, signups=base_signups),
    'bull': dict(first_eval_churn=0.50, repeat_eval_churn=0.10, signups=bull_signups),
}

horizons_weeks = {'1wk':1, '4wk':4, '12wk':12, '26wk':26}
results = {}
for name, params in scenarios.items():
    trace = simulate(26, params['first_eval_churn'], params['repeat_eval_churn'], params['signups'])
    results[name] = trace

arguments.new_string:
# Scenario definitions -- REVISED: given huge uncertainty whether conversion EVER
# recovers within 26wk (quality gap may widen faster than dev spend can close it,
# per "expected quality drifts upward over time" + possible further competitor shocks),
# base/bear now assume ZERO signups for the full 26-week window. Only bull assumes
# a recovery (optimistic: shocks stop, dev spend gains compound, gap closes).
def zero_signups(wk):
    return 0

def bull_signups(wk):
    if wk <= 8:
        return 0
    return min(200, (wk-8)*12)  # optimistic recovery

scenarios = {
    # bear: repeat-eval churn DEGRADES over time (tenure bonus capped, can't keep up
    # with continued ambient drift + occasional smaller shocks like day103-105)
    'bear': dict(first_eval_churn=0.65, repeat_eval_churn=0.28, signups=zero_signups),
    # base: repeat-eval churn holds near the one observed data point (14.8%), slight
    # conservative bump for estimation uncertainty (only 1 week of data so far)
    'base': dict(first_eval_churn=0.585, repeat_eval_churn=0.18, signups=zero_signups),
    'bull': dict(first_eval_churn=0.50, repeat_eval_churn=0.12, signups=bull_signups),
}

horizons_weeks = {'1wk':1, '4wk':4, '12wk':12, '26wk':26}
results = {}
for name, params in scenarios.items():
    trace = simulate(26, params['first_eval_churn'], params['repeat_eval_churn'], params['signups'])
    results[name] = trace

