import novamind_api as nm

print("=== ads_revenue by day, last 7 days ===")
r = nm.query("SELECT day, SUM(revenue) as rev, COUNT(DISTINCT customer_id) as n_cust, AVG(ads_strength) as avg_strength FROM ads_revenue WHERE day > 196 GROUP BY day ORDER BY day")
for row in r['rows']:
    print(row)

print("\n=== daily_usage table columns check / last 7 days ===")
try:
    r = nm.query("SELECT day, SUM(usage) as total_usage, COUNT(DISTINCT customer_id) as n FROM daily_usage WHERE day > 196 GROUP BY day ORDER BY day")
    for row in r['rows']:
        print(row)
except Exception as e:
    print("ERR", e)

print("\n=== leads per day, last 14 days (subscriptions table, status over time not tracked daily; try customers.created_day or similar) ===")
try:
    r = nm.query("SELECT lead_day, COUNT(*) as n FROM customers WHERE lead_day > 189 GROUP BY lead_day ORDER BY lead_day")
    for row in r['rows']:
        print(row)
except Exception as e:
    print("ERR1", e)
EOF
./novamind-operation python week29_calib.py

